// Built-in launcher artwork and a proportional distance-field font.
// Generated bytes live in ui_assets.cpp; see tools/bake_ui_assets.py.
#pragma once
#include <array>
#include <cstddef>

namespace mino::ui {
struct Image {
    const unsigned char *data;
    std::size_t size;
};
struct Glyph {
    int x, y, w, h;
    float xOffset, yOffset, advance;
};
struct FontFace {
    std::array<Glyph, 95> glyphs;
    float ascent;
};
inline constexpr float kFontEm = 48;
inline constexpr float kFontSpread = 8;
inline constexpr int kFontAtlasWidth = 1024, kFontAtlasHeight = 1024;
Image gameIcon(const char *id);
Image fontAtlas();
Image notesFontAtlas();
const FontFace &notesFontFace();
Image defaultWallpaper(bool portrait);
Image wallpaper(int index, bool portrait);
const FontFace &fontFace(bool bold);
} // namespace mino::ui
